// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Set owner to this contract via transferOwnership
        vm.prank(c.owner()); // pre-existing owner is address(0) initially
        c.transferOwnership(address(this));
        // Now this contract is owner
        address ownerBefore = c.owner();
        vm.prank(address(this));
        c.owned();
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "Owner should remain unchanged after owned()");
    }
}

